#include "unity.h"
#include "sh1106.h"

#include <string.h>

enum { CALLBACK_MAX_CALLS = 3, CALLBACK_MAX_BYTES = 65 };

typedef struct
{
    unsigned int calls;
    unsigned int fail_call;
    uint8_t address[CALLBACK_MAX_CALLS];
    uint16_t length[CALLBACK_MAX_CALLS];
    uint8_t bytes[CALLBACK_MAX_CALLS][CALLBACK_MAX_BYTES];
} send_record_t;

static send_record_t send_record;
static uint8_t pixels[128];

static bool recording_send(uint8_t address, uint8_t *bytes, uint16_t length)
{
    unsigned int call_index = send_record.calls;

    if (call_index < CALLBACK_MAX_CALLS)
    {
        send_record.address[call_index] = address;
        send_record.length[call_index] = length;
        if ((bytes != NULL) && (length <= CALLBACK_MAX_BYTES))
        {
            memcpy(send_record.bytes[call_index], bytes, length);
        }
    }
    send_record.calls++;
    return (send_record.fail_call == 0U) || (send_record.calls != send_record.fail_call);
}

static void assert_command_call(unsigned int index, uint8_t address, uint8_t page)
{
    TEST_ASSERT_EQUAL_UINT8(address, send_record.address[index]);
    TEST_ASSERT_EQUAL_UINT16(4U, send_record.length[index]);
    TEST_ASSERT_EQUAL_UINT8(0x00U, send_record.bytes[index][0]);
    TEST_ASSERT_EQUAL_UINT8((uint8_t)(0xB0U | page), send_record.bytes[index][1]);
    TEST_ASSERT_EQUAL_UINT8(0x02U, send_record.bytes[index][2]);
    TEST_ASSERT_EQUAL_UINT8(0x10U, send_record.bytes[index][3]);
}

static void assert_data_call(unsigned int index, uint8_t address, uint16_t pixel_offset)
{
    TEST_ASSERT_EQUAL_UINT8(address, send_record.address[index]);
    TEST_ASSERT_EQUAL_UINT16(65U, send_record.length[index]);
    TEST_ASSERT_EQUAL_UINT8(0x40U, send_record.bytes[index][0]);
    TEST_ASSERT_EQUAL_UINT8_ARRAY(&pixels[pixel_offset], &send_record.bytes[index][1], 64U);
}

